using System;using System.IO;using TavernLens;
class Check {static void Main(){string root=Path.Combine(Path.GetTempPath(),"TavernLens-test-"+Guid.NewGuid());Directory.CreateDirectory(Path.Combine(root,"Logs","active"));Directory.CreateDirectory(Path.Combine(root,"Logs","empty-newer"));string expected=Path.Combine(root,"Logs","active","Power.log");File.WriteAllText(expected,"test");if(TrackingSetup.FindLog(root)!=expected)throw new Exception("Missed nested log");string direct=Path.Combine(root,"Logs","Power.log");File.WriteAllText(direct,"test");File.SetLastWriteTimeUtc(direct,DateTime.UtcNow.AddMinutes(1));if(TrackingSetup.FindLog(root)!=direct)throw new Exception("Missed root log");if(TrackingSetup.FindLog(root+"missing")!="")throw new Exception("Missing folder");string text="[Other]\r\nKeep=true\r\n[Power]\r\nFilePrinting=false\r\n";string result=TrackingSetup.Configure(text);if(!result.Contains("Keep=true")||!result.Contains("[LoadingScreen]")||result.Contains("FilePrinting=false")||TrackingSetup.Configure(result)!=result)throw new Exception("Configuration merge");Console.WriteLine("4 log discovery/configuration checks passed");}}
